export interface Country {
  /** ISO 3166-1 alpha-2, upper case. */
  code: string;
  /** DataForSEO location_code for the whole country. */
  locationCode: number;
  /** DataForSEO language_code for Google Maps results in this country. */
  languageCode: string;
  /** English name. */
  name: string;
}

export const DEFAULT_COUNTRY = "US";
export const DEFAULT_LANGUAGE_CODE = "en";
/** Listed first in every country select. */
export const COMMON_COUNTRY_CODES = ["US", "GB", "CA", "AU", "IE", "NZ"] as const;

/** All countries, sorted by English name. */
export const COUNTRIES: readonly Country[] = TABLE.map(([code, locationCode, languageCode, name]) => ({ code, locationCode, languageCode, name }));
const BY_CODE = new Map(COUNTRIES.map((c) => [c.code, c]));

/** Every supported code, as a non-empty tuple, for `z.enum(COUNTRY_CODES)`. */
export const COUNTRY_CODES = COUNTRIES.map((c) => c.code) as [string, ...string[]];

/** Exact match: an upper-case ISO code that is in the table. */
export const isCountryCode = (value: unknown): value is string => typeof value === "string" && BY_CODE.has(value);

/** "de", " DE " → "DE"; anything that is not a supported code → null. */
export function normalizeCountry(value: string | null | undefined): string | null {
  const code = (value ?? "").trim().toUpperCase();
  return BY_CODE.has(code) ? code : null;
}

/** Country → DataForSEO location code. Unknown or empty → the United States, as before. */
export const locationCodeFor = (country: string | null | undefined): number =>
  (BY_CODE.get(normalizeCountry(country) ?? DEFAULT_COUNTRY) ?? BY_CODE.get(DEFAULT_COUNTRY)!).locationCode;

/** Country → DataForSEO language code for Google Maps results. Unknown or empty → English. */
export const languageCodeFor = (country: string | null | undefined): string => BY_CODE.get(normalizeCountry(country) ?? "")?.languageCode ?? DEFAULT_LANGUAGE_CODE;

/** English name of the country's Google Maps language ("German"), as DataForSEO names it. */
export const languageNameFor = (country: string | null | undefined): string => LANGUAGE_NAMES[languageCodeFor(country)] ?? "English";

/**
 * The note shown next to a country select: what language the lookups use. Null for English-language
 * countries, where there is nothing to point out.
 */
export function countryLanguageNote(country: string | null | undefined): string | null {
  if (languageCodeFor(country) === DEFAULT_LANGUAGE_CODE) return null;
  return `Google Maps results come in ${languageNameFor(country)}. AI questions are asked in English.`;
}

/** English name, or null for a code that is not in the table. */
export const countryName = (code: string | null | undefined): string | null => BY_CODE.get(normalizeCountry(code) ?? "")?.name ?? null;

export interface CountryOption {
  value: string;
  label: string;
}

const option = (c: Country): CountryOption => ({ value: c.code, label: c.name });
const commonSet = new Set<string>(COMMON_COUNTRY_CODES);

/** For a select: the common markets first, then every other country A–Z. Each country once. */
export const COUNTRY_OPTION_GROUPS: readonly { label: string; options: readonly CountryOption[] }[] = [
  { label: "Common", options: COMMON_COUNTRY_CODES.map((code) => option(BY_CODE.get(code)!)) },
  { label: "All other countries", options: COUNTRIES.filter((c) => !commonSet.has(c.code)).map(option) },
];

/** The same order as one flat list. */
export const COUNTRY_OPTIONS: readonly CountryOption[] = COUNTRY_OPTION_GROUPS.flatMap((g) => g.options);

const fold = (s: string) =>
  s
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[.’']/g, "")
    .replace(/&/g, " and ")
    .replace(/\s+/g, " ")
    .trim();

/** Names people often type that differ from the table's. */
const ALIASES: Record<string, string> = {
  uk: "GB", "great britain": "GB", england: "GB", scotland: "GB", wales: "GB", "northern ireland": "GB",
  usa: "US", "united states of america": "US", america: "US",
  "the netherlands": "NL", holland: "NL", turkey: "TR", "ivory coast": "CI", "czech republic": "CZ",
  "south korea": "KR", korea: "KR", burma: "MM", "cape verde": "CV", swaziland: "SZ", macau: "MO", vatican: "VA",
  "the bahamas": "BS", "the gambia": "GM", "republic of ireland": "IE",
};
const BY_NAME = new Map<string, string>([...COUNTRIES.map((c) => [fold(c.name), c.code] as const), ...Object.entries(ALIASES)]);

/**
 * A country as people write it in a spreadsheet: an ISO code ("DE", "de") or an English name
 * ("Germany", "United Kingdom", "UK"). Null when it is not recognised.
 */
export function countryFromText(text: string | null | undefined): string | null {
  const t = (text ?? "").trim();
  if (!t) return null;
  return normalizeCountry(t) ?? BY_NAME.get(fold(t)) ?? null;
}
